const value = $json;
const fail = (message) => { throw new Error(`Invalid Intake Resume input: ${message}`); };
const text = (name, required = false) => { const raw = value[name]; if (raw == null || raw === '') { if (required) fail(`${name} is required`); return null; } if (typeof raw !== 'string') fail(`${name} must be a string`); const out = raw.trim(); if (!out || out.length > 500) fail(`${name} must be non-empty and bounded`); return out; };
const trigger_kind = text('trigger_kind', true);
const source_event_key = text('source_event_key', true);
const tender_id = text('tender_id');
const analysis_run_id = text('analysis_run_id');
if (typeof value.manual_override !== 'boolean') fail('manual_override must be boolean');
let intent; let run_authoritative;
if (trigger_kind === 'tenderplan_mark') { if (!tender_id || analysis_run_id) fail('tenderplan_mark requires tender_id and forbids analysis_run_id'); if (value.manual_override) fail('manual override forbidden for tenderplan_mark'); intent = 'automatic'; run_authoritative = false; }
else if (trigger_kind === 'recovery_scan') { if (!analysis_run_id || tender_id) fail('recovery_scan requires analysis_run_id and forbids tender_id'); if (value.manual_override) fail('manual override forbidden for recovery_scan'); intent = 'automatic'; run_authoritative = true; }
else if (trigger_kind === 'manual') { if (!analysis_run_id || tender_id) fail('manual requires analysis_run_id and forbids tender_id'); if (!value.manual_override) fail('manual requires manual_override=true'); intent = 'manual'; run_authoritative = true; }
else fail(`unknown trigger_kind ${trigger_kind}`);
let observed_at = text('observed_at');
if (observed_at) { const parsed = Date.parse(observed_at); if (!Number.isFinite(parsed) || !/(?:Z|[+-]\d{2}:\d{2})$/u.test(observed_at)) fail('observed_at must be an ISO timestamp with timezone'); observed_at = new Date(parsed).toISOString(); }
return { json: { trigger_kind, source_event_key, tender_id, analysis_run_id, manual_override: value.manual_override, observed_at, intent, run_authoritative, source: trigger_kind === 'tenderplan_mark' ? 'tenderplan' : trigger_kind } };

const input = $input.first()?.json ?? {};
const documents = Array.isArray(input.documents) ? input.documents : [];
const runEntry = $('Apply Run Entry Policy').first().json;
const documentsTotal = Number(runEntry.documents_total);
const runStatus = String(input.run_status ?? '');
const supportedExtensions = new Set(['pdf', 'docx', 'xlsx', 'xls']);
const processableStatuses = new Set(['pending', 'processing', 'completed']);
const eligibleStatuses = new Set(['processing', 'ready_for_aggregation', 'aggregating']);
const indexes = documents.map((document) => Number(document.document_index));
const uniqueIndexes = new Set(indexes);
const completeIndexes = Number.isInteger(documentsTotal)
  && documentsTotal >= 0
  && documents.length === documentsTotal
  && uniqueIndexes.size === documentsTotal
  && indexes.every((index) => Number.isInteger(index) && index >= 1 && index <= documentsTotal);
const processable = documents.filter((document) =>
  processableStatuses.has(String(document.status ?? ''))
  && supportedExtensions.has(String(document.file_extension ?? '').trim().toLowerCase())
  && typeof document.download_url === 'string'
  && document.download_url.trim() !== ''
);
const identityComplete = processable.every((document) =>
  typeof document.id === 'string'
  && document.id.trim() !== ''
  && typeof document.file_name === 'string'
  && document.file_name.trim() !== ''
  && typeof document.mime_type === 'string'
  && document.mime_type.trim() !== ''
  && Number.isInteger(Number(document.file_size))
  && Number(document.file_size) >= 0
  && Number(document.file_size) <= 52428800
  && /^[0-9a-f]{64}$/iu.test(String(document.ingestion_metadata?.content_sha256 ?? ''))
);

let reason = null;
if (!eligibleStatuses.has(runStatus)) reason = 'terminal_run';
else if (!completeIndexes || !identityComplete) reason = 'manifest_incomplete';
else if (documents.some((document) => document.status === 'failed')) reason = 'failed_documents';
else if (processable.length === 0) reason = 'no_processable_documents';

return [{
  json: {
    ...input,
    documents_total: documentsTotal,
    should_dispatch_agentic_shadow: reason === null,
    agentic_shadow: {
      schema_version: 'tender_agentic_dispatch_v1',
      attempted: false,
      dispatched: false,
      acknowledged: false,
      no_op: false,
      success: null,
      job_id: null,
      status: null,
      outcome: null,
      action: null,
      error_code: null,
      reason
    }
  }
}];

const dispatch = $input.first()?.json ?? {};
const context = $('Prepare Agentic Shadow Dispatch').first().json;
if (dispatch.schema_version !== 'tender_agentic_dispatch_v1') {
  throw new Error('[Intake agentic shadow] Unexpected Dispatch contract.');
}
if (!context.analysis_run_id || context.source_event_key !== $('Classify Intake Event').first().json.source_event_key) {
  throw new Error('[Intake agentic shadow] source_event_key or analysis_run_id context mismatch.');
}
const status = typeof dispatch.status === 'string' ? dispatch.status : null;
const outcome = typeof dispatch.outcome === 'string' ? dispatch.outcome : null;
const dispatchAction = typeof dispatch.action === 'string' ? dispatch.action : null;
const noOp = dispatch.no_op === true;
const success = dispatch.success === false ? false : true;
const acknowledged = success && (noOp || ['ready', 'running', 'validating', 'completed'].includes(status));
const completionAction = acknowledged
  ? (noOp ? 'agentic_no_op' : 'agentic_dispatched')
  : 'manual_attention_required';
return [{
  json: {
    ...context,
    action: completionAction,
    should_dispatch_agentic_shadow: false,
    agentic_shadow: {
      schema_version: 'tender_agentic_dispatch_v1',
      attempted: true,
      dispatched: !noOp && status === 'running',
      acknowledged,
      no_op: noOp,
      success,
      job_id: typeof dispatch.job_id === 'string' ? dispatch.job_id : null,
      status,
      outcome,
      action: dispatchAction,
      error_code: typeof dispatch.error_code === 'string' ? dispatch.error_code : null,
      reason: noOp ? 'idempotent_no_op' : null
    }
  }
}];
